"""Canonical 1024-dimension slot registry for QUANTA.

Partitions the 1024 dimensions into eight isolated 128-slot bands:
- Band 0 (000–127): Universal NSM Primes, Classical Kinematics & Continuous Physics
- Band 1 (128–255): Structural Valencies, Grammatical Tense/Aspect, Code AST & Concurrency Topologies
- Band 2 (256–383): Logic Quantifiers (∀, ∃, ∃!), Variable Binding Registers & Query Unification Heads
- Band 3 (384–511): 128 Data-Driven ConceptNet Taxonomies, Scientific Domains & Entity Types
- Band 4 (512–639): 128 Data-Driven ConceptNet Actions, Functional Affordances & Cyber-Physical Properties
- Band 5 (640–767): Theory of Mind, 3-Tier Nested Beliefs, Teleological Goals & Pragmatic Intent
- Band 6 (768–895): Epistemic Proof Solvers, s(CASP) Invariants & Deontic Normative Logic
- Band 7 (896–1023): Spatio-Temporal Mereotopology (Allen, RCC-8) & Pearl Causal Counterfactual DAGs
"""

from __future__ import annotations
from dataclasses import dataclass
import enum
import json
from pathlib import Path
from typing import Dict, List, Optional, Union

class BandContract(str, enum.Enum):
    """Polymorphic contract applied to dimensions depending on their Band."""
    EPISTEMIC = "EPISTEMIC"      # Bands 0, 3, 4, 5, 6, 7: Truth & Uncertainty (Belnap FOUR)
    STRUCTURAL = "STRUCTURAL"    # Band 1: Valencies, AST Topology, Concurrency Routing
    REGISTER = "REGISTER"        # Band 2: Formal Logic Quantifiers & Variable Scoping


class SlotBand(enum.IntEnum):
    BAND_0_NSM_KINEMATICS = 0
    BAND_1_VALENCIES_TOPOLOGY = 1
    BAND_2_LOGIC_VARIABLES = 2
    BAND_3_ONTOLOGY_STRUCTURES = 3
    BAND_4_AFFORDANCES_OPERATIONS = 4
    BAND_5_TOM_PRAGMATICS = 5
    BAND_6_PROOF_DEONTICS = 6
    BAND_7_SPATIOTEMPORAL_CAUSAL = 7
    # Backward compatibility aliases
    BAND_2_ONTOLOGY_MODALITY = 3
    BAND_3_EPISTEMIC_METARULES = 6


BAND_CONTRACTS: Dict[SlotBand, BandContract] = {
    SlotBand.BAND_0_NSM_KINEMATICS: BandContract.EPISTEMIC,
    SlotBand.BAND_1_VALENCIES_TOPOLOGY: BandContract.STRUCTURAL,
    SlotBand.BAND_2_LOGIC_VARIABLES: BandContract.REGISTER,
    SlotBand.BAND_3_ONTOLOGY_STRUCTURES: BandContract.EPISTEMIC,
    SlotBand.BAND_4_AFFORDANCES_OPERATIONS: BandContract.EPISTEMIC,
    SlotBand.BAND_5_TOM_PRAGMATICS: BandContract.EPISTEMIC,
    SlotBand.BAND_6_PROOF_DEONTICS: BandContract.EPISTEMIC,
    SlotBand.BAND_7_SPATIOTEMPORAL_CAUSAL: BandContract.EPISTEMIC,
}


@dataclass(frozen=True)
class SlotDefinition:
    index: int
    name: str
    band: SlotBand
    category: str
    description: str

    @property
    def contract(self) -> BandContract:
        return BAND_CONTRACTS.get(self.band, BandContract.EPISTEMIC)

